from typing import Dict, Set


# Helpers
def build_patient_to_disease(disease_ids: Dict[str, Set[str]]) -> Dict[str, str]:
    out = {}
    for disease, ids in disease_ids.items():
        for sid in ids:
            sid = str(sid).strip()
            if sid:
                out[sid] = disease
    return out


